 async void PopulateLauncherDetails(string file,TextBlock title,TextBlock package,TextBlock detail,Button install){
  install.IsEnabled=false;
  if(!File.Exists(file)){package.Text="安装包不可用";detail.Text=System.IO.Path.GetFileName(file);return;}
  var info=await InspectApk(file);if(info.Error==null){title.Text=info.Name;package.Text=info.Package;detail.Text=System.IO.Path.GetFileName(file)+" · "+(new FileInfo(file).Length/1048576.0).ToString("F1")+" MB\n版本 "+info.Version;install.IsEnabled=serial!="";}else{package.Text="无法识别安装包";package.ToolTip=info.Error;detail.Text=System.IO.Path.GetFileName(file);}
 }
