 void Col(string title,string key,int width){grid.Columns.Add(new DataGridTextColumn{Header=title,Binding=new System.Windows.Data.Binding(key),IsReadOnly=true,Width=width});}
 IEnumerable<Package> VisiblePackages(){string term=search==null?"":search.Text.Trim();return packages.Where(a=>((page=="恢复列表"||page=="恢复应用")?a.State!="已安装":a.State=="已安装"||a.State=="已停用")&&(page!="步骤4"||(a.IsLauncher&&a.System))&&(page!="步骤3"||SelectedCategory=="全部应用"||a.Group==SelectedCategory||a.Risk==SelectedCategory)&&(term==""||(a.Name+" "+a.Id+" "+a.Path+" "+a.Reason).IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0));}
 void Bind(){if(grid!=null&&(page.StartsWith("步骤")||page=="恢复列表"||page=="应用管理"||page=="AI 分析"||page=="恢复应用")){foreach(var p in packages){p.HighRisk=usingAi&&p.Risk=="疑似系统组件";if(string.IsNullOrWhiteSpace(p.AiOpinion))p.AiOpinion=p.Reason;}grid.ItemsSource=VisiblePackages().ToList();UpdateSelectionToggle();}}
 void AddSelectionToggle(Panel panel){Add(panel,"全部选定",SelectVisible);selectionToggle=(Button)panel.Children[panel.Children.Count-1];selectionToggle.ToolTip="选定或取消当前筛选中可操作的应用";}
 Button selectionToggle;
 bool Selectable(Package p){return page=="恢复列表"?p.State!="已安装":p.State=="已安装"||p.State=="已停用";}
 void UpdateSelectionToggle(){if(selectionToggle==null)return;var rows=VisiblePackages().Where(Selectable).ToList();selectionToggle.Content=rows.Count>0&&rows.All(p=>p.Pick)?"取消选定":"全部选定";selectionToggle.IsEnabled=rows.Count>0;}
 void SelectVisible(){var rows=VisiblePackages().Where(Selectable).ToList();bool pick=!rows.All(p=>p.Pick);foreach(var p in rows)p.Pick=pick;UpdateSelectionToggle();}
 void SelectionMouseDown(object sender,System.Windows.Input.MouseButtonEventArgs e){if(e.ChangedButton!=System.Windows.Input.MouseButton.Left)return;DependencyObject node=e.OriginalSource as DependencyObject;while(node!=null&&!(node is DataGridCell))node=VisualTreeHelper.GetParent(node);var cell=node as DataGridCell;if(cell==null||cell.Column.DisplayIndex!=0)return;var p=cell.DataContext as Package;if(p==null)return;e.Handled=true;if(Selectable(p)){p.Pick=!p.Pick;UpdateSelectionToggle();}}
 void ConfigureSelectionColumn(){var check=new FrameworkElementFactory(typeof(CheckBox));check.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);check.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);check.SetValue(UIElement.FocusableProperty,false);check.SetValue(UIElement.IsHitTestVisibleProperty,false);check.SetBinding(System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty,new System.Windows.Data.Binding("Pick"){Mode=System.Windows.Data.BindingMode.OneWay});grid.Columns.Add(new DataGridTemplateColumn{Header="选择",Width=48,MinWidth=48,MaxWidth=48,CanUserResize=false,IsReadOnly=true,CellTemplate=new DataTemplate{VisualTree=check}});grid.PreviewMouseDown+=SelectionMouseDown;grid.PreviewKeyDown+=(s,e)=>{var cell=KeyboardCell();if(e.Key==System.Windows.Input.Key.Space&&cell!=null&&cell.Column.DisplayIndex==0){var p=cell.DataContext as Package;e.Handled=true;if(p!=null&&Selectable(p)){p.Pick=!p.Pick;UpdateSelectionToggle();}}};}
 DataGridCell KeyboardCell(){DependencyObject node=System.Windows.Input.Keyboard.FocusedElement as DependencyObject;while(node!=null&&!(node is DataGridCell))node=VisualTreeHelper.GetParent(node);return node as DataGridCell;}
 bool ScanReady(){return scannedFor==serial&&serial!=""&&packages.Count>0;}
 void UseOriginalRules(){usingAi=false;foreach(var p in packages){p.AiOpinion=null;p.Pick=false;p.Risk=IsProtected(p.Id)?"保护":"自动分类";p.Reason="自动分类，仅供人工复核";}Classify();SelectedCategory="普通精简";Show("步骤3");}
 void Classify(){foreach(var p in packages){p.Group=OriginalCategory(p.Id);if(p.Risk==null||p.Risk=="待分析"||p.Risk=="保护"||p.Risk=="自动分类"){p.Risk=IsProtected(p.Id)?"保护":"自动分类";p.Reason=ClassifyPackage(p.Id).reason;}}classifiedFor=serial;foreach(string mode in new[]{"normal","deep","desktop"}){string group=new Dictionary<string,string>{{"normal","普通精简"},{"deep","深度精简"},{"desktop","桌面精简"}}[mode];File.WriteAllLines(DeviceDir+"/"+mode+".txt",packages.Where(p=>p.Group==group).Select(p=>p.Id));}}
 void ApplyMetadata(){var cacheFile=DeviceDir+"/names.json";if(File.Exists(cacheFile)){try{var cached=new JavaScriptSerializer().Deserialize<List<Package>>(File.ReadAllText(cacheFile));foreach(var p in packages){var old=cached.FirstOrDefault(a=>a.Id==p.Id&&a.Path==p.Path);if(old!=null){p.Name=old.Name;p.NameSource=old.NameSource;}}}catch{}}Classify();}
 static public string PreferredLabel(string dump){var matches=Regex.Matches(dump,@"^application-label(?:-([^:]+))?:'([^']*)'",RegexOptions.Multiline);string label="";int score=-1;foreach(Match m in matches){string locale=m.Groups[1].Value.ToLowerInvariant();int rank=locale=="zh-cn"||locale=="zh-hans"||locale=="zh-rcn"?5:locale=="zh"?4:locale.StartsWith("zh")?3:locale==""?2:0;if(rank>score&&m.Groups[2].Value!=""){score=rank;label=m.Groups[2].Value;}}return label;}
 void Deep(){Run(async()=>{cancellableTask=true;CheckCancelled();await Scan();int i=0;foreach(var a in packages.Where(x=>x.State!="已卸载").ToList()){CheckCancelled();i++;if(scanProgress!=null)scanProgress.Text="识别中文名称 "+i+" / "+packages.Count+" · "+a.Id;string temp=DeviceDir+"/label-"+Guid.NewGuid().ToString("N")+".apk";try{string paths=await Shell("pm path "+a.Id);string apk=paths.Split('\n').First(x=>x.StartsWith("package:")).Substring(8).Trim();await Adb("pull "+Q(apk)+" "+Q(temp));string dump=await ProcessRun(Root+"tools/aapt.exe","dump badging "+Q(temp),30000);string label=PreferredLabel(dump);if(label!=""){a.Name=label;a.NameSource=Regex.IsMatch(label,@"\p{IsCJKUnifiedIdeographs}")?"中文资源":"应用原名（无中文资源）";}}catch(Exception ex){a.NameSource="读取失败";Report(a.Id+"：名称读取失败，保留包名。"+ex.Message);}finally{if(File.Exists(temp))File.Delete(temp);}File.WriteAllText(DeviceDir+"/names.json",new JavaScriptSerializer().Serialize(packages));CheckCancelled();}scannedFor=serial;Classify();await RefreshSystemFlags();await RefreshHomes();File.WriteAllText(DeviceDir+"/names.json",new JavaScriptSerializer().Serialize(packages));File.WriteAllText(DeviceDir+"/scan.json",new JavaScriptSerializer().Serialize(packages));Show("步骤1");if(scanProgress!=null)scanProgress.Text="深度扫描完成 · "+packages.Count+" 个应用；已生成普通、深度和桌面三份参考配置。";Report("深度扫描完成，优先显示中文标签。");});}
 async Task RefreshSystemFlags(){try{var s=new HashSet<string>((await Shell("pm list packages -s")).Split('\n').Select(x=>x.Trim().Replace("package:","")));foreach(var p in packages)p.System=s.Contains(p.Id);}catch{foreach(var p in packages)p.System=!p.Path.StartsWith("/data/app/");}}
 async Task RefreshHomes(){homes.Clear();homeQueryOk=false;string result="";try{result=await Shell("cmd package query-activities --brief -a android.intent.action.MAIN -c android.intent.category.HOME");}catch{}if(!Regex.IsMatch(result,@"[\w.]+/[\w.$]+"))try{result=await Shell("pm query-activities --brief -a android.intent.action.MAIN -c android.intent.category.HOME");}catch{}foreach(Match m in Regex.Matches(result,@"([A-Za-z0-9_.]+)/([A-Za-z0-9_.$]+)")){homes[m.Groups[1].Value]=m.Value;}homeQueryOk=homes.Count>0;foreach(var p in packages)p.IsLauncher=homes.ContainsKey(p.Id);}
 string ReadLauncher(){string f=DeviceDir+"/new-launcher.txt";newLauncher=File.Exists(f)?File.ReadAllText(f).Trim():"";return newLauncher;}
 void InstallLauncher(string file){if(!Confirm("安装这个桌面？安装后请在电视上确认运行。"))return;Run(async()=>{var dump=await ProcessRun(Root+"tools/aapt.exe","dump badging "+Q(file),30000);var m=Regex.Match(dump,@"package: name='([A-Za-z0-9_.]+)'");if(!m.Success)throw new Exception("无法读取桌面包名");string id=m.Groups[1].Value;string result=await Adb("install -r "+Q(file));if(!Regex.IsMatch(result,@"\bSuccess\b"))throw new Exception(result);string installed=await Shell("pm path "+id);if(!installed.Contains("package:"))throw new Exception("安装后未找到桌面");newLauncher=id;File.WriteAllText(DeviceDir+"/new-launcher.txt",id);await Scan();await RefreshHomes();Show("步骤2");Report("新桌面安装成功："+id+"，可按需设为默认并验证。");});}
 async Task<bool> VerifyNewHome(){ReadLauncher();if(newLauncher=="")return false;string paths=await Shell("pm path "+newLauncher);if(!paths.Contains("package:"))return false;await RefreshHomes();if(!homes.ContainsKey(newLauncher))return false;string current="";try{current=await Shell("cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME");}catch{}if(!current.Contains(newLauncher+"/"))try{current=await Shell("pm resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME");}catch{}return current.Split('\n').Any(x=>x.Trim().StartsWith(newLauncher+"/",StringComparison.Ordinal));}
 void SetNewHome(){Run(async()=>{ReadLauncher();await RefreshHomes();if(newLauncher==""||!homes.ContainsKey(newLauncher))throw new Exception("请先安装本工具附带的新桌面，且电视能识别它为 HOME 应用。");Report(await Shell("cmd package set-home-activity --user 0 "+homes[newLauncher]));if(!await VerifyNewHome())throw new Exception("未能确认新桌面为默认，请在电视设置中手动选择默认桌面。");Report("新桌面已验证为默认。");});}
 void RemoveOldHome(){Change("uninstall");}
 bool IsCore(string id){return ClassifyPackage(id).core;}
 void RecordChange(string mode,string id,string result){if(mode!="restore")UpdateUndoResult(id,result);File.AppendAllText(Data+"/history.tsv",serial+"\t"+mode+"\t"+id+"\t"+DateTime.Now+"\t"+result.Replace("\n"," ").Replace("\r","")+"\n");}
 void LoadHistoryEntries(){string f=Data+"/history.tsv";if(!File.Exists(f))return;foreach(string line in File.ReadAllLines(f)){string[] c=line.Split('\t');if(c.Length<5||c[0]!=serial||c[1]!="uninstall"||!Regex.IsMatch(c[2],@"^[A-Za-z0-9_.]+$")||!c[4].Contains("Success")||packages.Any(p=>p.Id==c[2]))continue;packages.Add(new Package{Id=c[2],Name=c[2],Path="系统不再列出，请从 APK 备份恢复",State="需 APK 备份",Group=OriginalCategory(c[2]),Risk="谨慎卸载",Reason="来自本设备删除记录"});}}
 void FactoryReset(){if(Prompt("恢复出厂是可选的补救措施，会清空电视数据。只进入 Recovery，由你在电视端决定是否清除。输入“重新再来”继续。","")!="重新再来")return;if(!Confirm("确认让当前电视进入 Recovery？请先保存需要的数据。"))return;Run(async()=>{await StopMirror();await Adb("reboot recovery");Report("已发送进入 Recovery 命令；是否恢复出厂由你在电视上确认。");});}
}


